   670  struct VariationSelectorRecord
   671  {
   672    inline glyph_variant_t get_glyph (hb_codepoint_t codepoint,
   673                                      hb_codepoint_t *glyph,
   674                                      const void *base) const
   675    {
   676      int i;
   677      const DefaultUVS &defaults = base+defaultUVS;
   678      i = defaults.bsearch (codepoint);
   679      if (i != -1)
   680        return GLYPH_VARIANT_USE_DEFAULT;
   681      const NonDefaultUVS &nonDefaults = base+nonDefaultUVS;
   682      i = nonDefaults.bsearch (codepoint);
   683      if (i != -1 && nonDefaults[i].glyphID)
   684      {
   685        *glyph = nonDefaults[i].glyphID;
   686         return GLYPH_VARIANT_FOUND;
   687      }
   688      return GLYPH_VARIANT_NOT_FOUND;
   689    }
   690
   691    inline void collect_unicodes (hb_set_t *out, const void *base) const
   692    {
   693      (base+defaultUVS).collect_unicodes (out);
   694      (base+nonDefaultUVS).collect_unicodes (out);
   695    }
   696
   697    inline int cmp (const hb_codepoint_t &variation_selector) const
   698    {
   699      return varSelector.cmp (variation_selector);
   700    }
   701
   702    inline bool sanitize (hb_sanitize_context_t *c, const void *base) const
   703    {
   704      TRACE_SANITIZE (this);
   705      return_trace (c->check_struct (this) &&
   706                    defaultUVS.sanitize (c, base) &&
   707                    nonDefaultUVS.sanitize (c, base));
   708    }
   709
   710    HBUINT24      varSelector;    /* Variation selector. */
   711    LOffsetTo<DefaultUVS>
   712                  defaultUVS;     /* Offset to Default UVS Table. May be 0. */
   713    LOffsetTo<NonDefaultUVS>
   714                  nonDefaultUVS;  /* Offset to Non-Default UVS Table. May be 0. */
   715    public:
   716    DEFINE_SIZE_STATIC (11);
   717  };
