   340    template <typename Type, typename ValueType>
   760    inline Stored * do_create (void) const
   761    {
   762      Stored *p = this->template call_create<Stored, Funcs> ();
   763      if (unlikely (!p))
   764        p = const_cast<Stored *> (Funcs::get_null ());
   765      return p;
   766    }
   767    static inline void do_destroy (Stored *p)
   768    {
   769      if (p && p != Funcs::get_null ())
   770        Funcs::destroy (p);
   771    }
   772
   773    inline const Returned * operator -> (void) const { return get (); }
   774    inline const Returned & operator * (void) const { return *get (); }
   775
   776    inline Data * get_data (void) const
   777    {
   778      return *(((Data **) this) - WheresData);
   779    }
   780
   781    inline Stored * get_stored (void) const
   782    {
   783    retry:
   784      Stored *p = this->instance.get ();
   785      if (unlikely (!p))
   786      {
   787        p = do_create ();
   788        if (unlikely (!this->instance.cmpexch (nullptr, p)))
   789        {
   790          do_destroy (p);
   791          goto retry;
   792        }
   793      }
   794      return p;
   795    }
   796    inline Stored * get_stored_relaxed (void) const
   797    {
   798      return this->instance.get_relaxed ();
   799    }
   800
   801    inline void set_stored (Stored *instance_)
   802    {
   803      /* This *must* be called when there are no other threads accessing.
   804       * However, to make TSan, etc, happy, we using cmpexch. */
   805    retry:
   806      Stored *p = this->instance.get ();
   807      if (unlikely (!this->instance.cmpexch (p, instance_)))
   808        goto retry;
   809      do_destroy (p);
   810    }
   811
   812    inline const Returned * get (void) const { return Funcs::convert (get_stored ()); }
   813    inline const Returned * get_relaxed (void) const { return Funcs::convert (get_stored_relaxed ()); }
   814    inline Returned * get_unconst (void) const { return const_cast<Returned *> (Funcs::convert (get_stored ())); }
   815
   816    /* To be possibly overloaded by subclasses. */
   817    static inline Returned* convert (Stored *p) { return p; }
   818
   819    /* By default null/init/fini the object. */
   820    static inline const Stored* get_null (void) { return &Null(Stored); }
   821    static inline Stored *create (Data *data)
   822    {
   823      Stored *p = (Stored *) calloc (1, sizeof (Stored));
   824      if (likely (p))
   825        p->init (data);
   826      return p;
   827    }
   828    static inline Stored *create (void)
   829    {
   830      Stored *p = (Stored *) calloc (1, sizeof (Stored));
   831      if (likely (p))
   832        p->init ();
   833      return p;
   834    }
   835    static inline void destroy (Stored *p)
   836    {
   837      p->fini ();
   838      free (p);
   839    }
   840
   841    private:
   842    /* Must only have one pointer. */
   843    hb_atomic_ptr_t<Stored *> instance;
   844  };
